"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["5284"],{4257(e,t,n){n.r(t),n.d(t,{metadata:()=>i,default:()=>h,frontMatter:()=>r,contentTitle:()=>s,toc:()=>l,assets:()=>d});var i=JSON.parse('{"id":"SoftwareEngineering/technical-debt","title":"Technical Debt","description":"Technical debt is the implied cost of future rework caused by choosing an easier, faster solution now instead of a better, more thorough approach. Like financial debt, it\'s not inherently bad \u2014 it\'s a tool, used well or poorly depending on whether it\'s taken on deliberately and paid down intentionally.","source":"@site/docs/SoftwareEngineering/20-technical-debt.md","sourceDirName":"SoftwareEngineering","slug":"/SoftwareEngineering/technical-debt","permalink":"/Mindstack/docs/SoftwareEngineering/technical-debt","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":20,"frontMatter":{"title":"Technical Debt","sidebar_label":"Technical Debt","sidebar_position":20},"sidebar":"softwareEngineeringSidebar","previous":{"title":"Code Review","permalink":"/Mindstack/docs/SoftwareEngineering/code-review"},"next":{"title":"Documentation","permalink":"/Mindstack/docs/SoftwareEngineering/documentation"}}'),a=n(4848),o=n(8453);let r={title:"Technical Debt",sidebar_label:"Technical Debt",sidebar_position:20},s="Technical Debt",d={},l=[{value:"The Debt Metaphor, Taken Seriously",id:"the-debt-metaphor-taken-seriously",level:2},{value:"Types of Technical Debt",id:"types-of-technical-debt",level:2},{value:"Deliberate Debt",id:"deliberate-debt",level:3},{value:"Accidental / Reckless Debt",id:"accidental--reckless-debt",level:3},{value:"Bit Rot / Unavoidable Debt",id:"bit-rot--unavoidable-debt",level:3},{value:"Making Debt Visible",id:"making-debt-visible",level:2},{value:"Communicating Debt to Non-Engineers",id:"communicating-debt-to-non-engineers",level:2},{value:"The Cost of NOT Paying Down Debt",id:"the-cost-of-not-paying-down-debt",level:2},{value:"Practical Debt Management",id:"practical-debt-management",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function c(e){let t={code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",ul:"ul",...(0,o.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"technical-debt",children:"Technical Debt"})}),"\n",(0,a.jsx)(t.p,{children:"Technical debt is the implied cost of future rework caused by choosing an easier, faster solution now instead of a better, more thorough approach. Like financial debt, it's not inherently bad \u2014 it's a tool, used well or poorly depending on whether it's taken on deliberately and paid down intentionally."}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"the-debt-metaphor-taken-seriously",children:"The Debt Metaphor, Taken Seriously"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:"Financial debt:\n  You borrow money now, get something you need immediately, and pay\n  it back later WITH INTEREST. Reasonable when the immediate need is\n  real and you have a genuine plan to repay it. Dangerous when it\n  accumulates without a repayment plan, or when the interest rate\n  (the ongoing cost) is higher than you realized when you took it on.\n\nTechnical debt:\n  You ship a quick, imperfect solution now, get a real business\n  benefit (shipped feature, met deadline, validated an idea) sooner,\n  and accept that the imperfect solution will cost MORE to properly\n  fix or extend later than if you'd done it right the first time.\n  Reasonable when the immediate need is real and there's a genuine\n  plan to address it. Dangerous when it accumulates silently, with\n  no tracking and no repayment plan, until the codebase becomes\n  something the team actively dreads working in.\n"})}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"types-of-technical-debt",children:"Types of Technical Debt"}),"\n",(0,a.jsx)(t.h3,{id:"deliberate-debt",children:"Deliberate Debt"}),"\n",(0,a.jsx)(t.p,{children:"Taken on knowingly, usually under a real deadline or to validate an idea before investing more heavily."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:"Example: \"We're hardcoding this configuration value instead of\nbuilding a proper admin UI for it, because we need to ship this\nfeature by Friday, and we don't yet know if this feature will even\nbe kept after the initial user feedback.\"\n\nThis is a REASONABLE trade-off if:\n  - It's made consciously, not accidentally\n  - The team is aware of the trade-off (not hidden from teammates\n    or from whoever owns the roadmap)\n  - There's at least a rough plan for revisiting it if the feature\n    proves out and needs to become more robust\n"})}),"\n",(0,a.jsx)(t.h3,{id:"accidental--reckless-debt",children:"Accidental / Reckless Debt"}),"\n",(0,a.jsx)(t.p,{children:"Taken on without realizing it, or knowingly without any plan to address it."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:'Example: a team ships code without tests, "just this once," under\ndeadline pressure \u2014 and this becomes the unstated norm for the next\ntwo years, because there was never a deliberate decision to revisit it.\n\nThis is the dangerous kind: it compounds silently, because nobody\nconsciously decided to accept the trade-off \u2014 it just happened, and\nkept happening, until the codebase\'s overall quality degraded far\nmore than anyone individually intended.\n'})}),"\n",(0,a.jsx)(t.h3,{id:"bit-rot--unavoidable-debt",children:"Bit Rot / Unavoidable Debt"}),"\n",(0,a.jsx)(t.p,{children:"Debt that accumulates not from a poor decision, but simply from the world changing around otherwise-fine code."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:"Example: a dependency you correctly chose two years ago is now\ndeprecated, or a design that was appropriate for the traffic/scale\nyou had a year ago no longer fits your current traffic/scale (see\nfile 16, Scalability Patterns).\n\nThis isn't a mistake anyone made \u2014 it's the natural cost of a system\nexisting and its environment changing around it. Still needs to be\ntracked and paid down like any other form of debt.\n"})}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"making-debt-visible",children:"Making Debt Visible"}),"\n",(0,a.jsx)(t.p,{children:"The single most important practice: technical debt that isn't tracked doesn't get paid down \u2014 it just accumulates until it becomes a crisis."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:'Concrete ways to make debt visible:\n\n  A dedicated backlog/ticket for each known piece of debt, with\n  enough context that someone OTHER than the person who wrote it\n  could understand and address it later\n\n  A TODO comment WITH a ticket reference and owner, not a vague\n  floating note:\n    # TODO(alice, JIRA-4521): this uses a naive O(n\xb2) algorithm;\n    # fine for current data volume (~1000 items), revisit if it\n    # grows significantly \u2014 see ticket for the specific threshold\n    # where this becomes a real problem\n\n  Explicitly calling it out in the PR description that introduces it:\n    "Note: this hardcodes the tax rate rather than making it\n    configurable, since we\'re not yet sure this feature will be\n    kept post-launch. If it sticks around, JIRA-4521 tracks making\n    this configurable properly."\n\n  A recurring team ritual (even quarterly) to review the accumulated\n  debt backlog and deliberately decide what to pay down next,\n  alongside regular feature work \u2014 not waiting for debt to become\n  painful enough to force an emergency response\n'})}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"communicating-debt-to-non-engineers",children:"Communicating Debt to Non-Engineers"}),"\n",(0,a.jsx)(t.p,{children:"This is often the hardest part \u2014 technical debt is invisible to anyone who can't read the code, which makes it easy for it to lose out to visible, demonstrable feature work when priorities are set."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:'What doesn\'t work well:\n  "We need to refactor the payment module" \u2014 abstract, no clear\n  connection to anything a product manager or business stakeholder\n  can weigh against other priorities.\n\nWhat works better \u2014 translate debt into business terms:\n  "The current payment code makes adding a new payment provider take\n  roughly 3 weeks; a focused 1-week investment now would bring that\n  down to about 3 days for every FUTURE payment provider we add" \u2014\n  concrete, comparable against other roadmap priorities, and framed\n  in terms of future velocity, which is something a non-engineer\n  stakeholder can genuinely reason about and prioritize against.\n\n  "This part of the system has caused 4 production incidents in the\n  last quarter, each taking an average of 6 engineer-hours to\n  resolve \u2014 addressing the underlying design issue would cost\n  roughly 2 weeks of focused work" \u2014 grounds the debt in a concrete,\n  already-experienced cost, not a hypothetical future one.\n\nFraming debt in terms of velocity, risk, or already-incurred cost\n(rather than abstract code quality) is what makes it possible to\ngenuinely weigh against feature work in prioritization conversations.\n'})}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"the-cost-of-not-paying-down-debt",children:"The Cost of NOT Paying Down Debt"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:"Debt compounds \u2014 code with existing debt tends to accumulate MORE\ndebt faster than clean code does, for a few concrete reasons:\n\n  New features built on top of a messy foundation inherit and often\n  amplify that mess, because there's no clean structure to extend\n  cleanly\n\n  Engineers become reluctant to refactor code they don't fully\n  understand or trust \u2014 so problems get worked AROUND instead of\n  fixed, adding yet another layer of workaround on top of the\n  original problem\n\n  Onboarding new team members to a debt-heavy codebase takes\n  longer, and they're more likely to unknowingly introduce MORE\n  debt, because the \"right way to do things here\" isn't evident\n  from the existing code\n\nThis compounding effect is why \"we'll deal with it later\" often\nbecomes progressively more expensive to actually act on the longer\nit's deferred \u2014 not because the original debt itself grew, but\nbecause more and more code came to depend on and inherit its problems.\n"})}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"practical-debt-management",children:"Practical Debt Management"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:'1. Make debt visible (tracked, not just remembered) \u2014 see above.\n\n2. Allocate DEDICATED time for paying it down, don\'t rely on\n   "whenever there\'s spare time" (spare time in most teams tends\n   toward zero, indefinitely, without deliberate allocation).\n   Common patterns: a fixed percentage of each sprint/cycle reserved\n   for debt work, or periodic dedicated "focus" time blocks.\n\n3. Prioritize debt like any other work, using its actual, demonstrated\n   impact \u2014 the debt costing the team 6 hours of production incident\n   response every month deserves priority over the debt that\'s\n   theoretically imperfect but has never actually caused a problem.\n\n4. Prevent NEW reckless debt through code review (file 19) and\n   team standards (file 01, file 02) \u2014 the highest-leverage moment\n   to address debt is before it\'s merged, not after it\'s compounded\n   for months.\n\n5. Distinguish "this code is imperfect" from "this code is actively\n   costing us" \u2014 not all imperfection is debt worth actively paying\n   down; focus effort on debt with a REAL, demonstrated cost (this\n   connects to YAGNI, file 04 \u2014 perfecting code with no real ongoing\n   cost is its own form of wasted effort).\n'})}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"tips",children:"Tips"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"Track technical debt the same way you'd track a feature request \u2014 a ticket, with context, not just a mental note or a vague comment that will lose all context within weeks."}),"\n",(0,a.jsx)(t.li,{children:'Translate debt into business terms (velocity impact, incident cost) when communicating it to non-engineering stakeholders \u2014 abstract "code quality" arguments rarely win against visible, demonstrable feature work in prioritization conversations.'}),"\n",(0,a.jsx)(t.li,{children:"Distinguish deliberate debt (a conscious, reasonable trade-off with a plan) from reckless debt (unconscious, no plan) \u2014 the goal isn't zero debt, it's debt that's taken on and managed deliberately."}),"\n",(0,a.jsx)(t.li,{children:'Allocate dedicated time for debt repayment rather than hoping for leftover time \u2014 "whenever there\'s spare time" reliably becomes "never" in most real teams.'}),"\n",(0,a.jsx)(t.li,{children:"Focus debt-paydown effort on debt with a demonstrated, real cost (recurring incidents, measurably slower feature development) rather than theoretical imperfection with no actual observed impact."}),"\n"]}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"summary",children:"Summary"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"Technical debt is the implied future cost of a faster, imperfect solution chosen now \u2014 like financial debt, it's a tool, not inherently bad, as long as it's taken on deliberately and tracked."}),"\n",(0,a.jsx)(t.li,{children:"Deliberate debt (conscious trade-off, known, with a plan) is manageable; accidental/reckless debt (unconscious, unplanned) is what actually causes codebases to degrade badly over time."}),"\n",(0,a.jsx)(t.li,{children:"Make debt visible through tracked tickets, contextual TODO comments, and explicit callouts in PR descriptions \u2014 untracked debt doesn't get paid down, it just silently accumulates."}),"\n",(0,a.jsx)(t.li,{children:"Communicate debt to non-engineers in terms of velocity, risk, and already-incurred cost, not abstract code quality \u2014 this is what makes it possible to prioritize against visible feature work."}),"\n",(0,a.jsx)(t.li,{children:"Debt compounds: messy foundations produce more debt faster, and reluctance to touch untrusted code leads to workarounds stacked on workarounds \u2014 deferring paydown tends to make it progressively more expensive to eventually address."}),"\n",(0,a.jsx)(t.li,{children:"Manage debt deliberately: track it, allocate dedicated time for it, prioritize by demonstrated real-world impact, and prevent new reckless debt through code review and team standards."}),"\n"]})]})}function h(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>s});var i=n(6540);let a={},o=i.createContext(a);function r(e){let t=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),i.createElement(o.Provider,{value:t},e.children)}}}]);